4 Geocoding

postcodes &lt;- unique(biz_56111$postal_code)

url &lt;- "https://onemap.gov.sg/api/common/elastic/search"


found &lt;-data.frame()
not_found &lt;- data.frame(postcode = character())

for(pc in postcodes) {
  query &lt;- list(
    searchVal = pc,
    returnGeom = "Y",
    getAddrDetails = "Y",
    pageNum = "1"
  )

  res &lt;- GET(url,query = query)
  json &lt;- content(res)

  if(json$found !=0) {
    df &lt;- as.data.frame(json$results,stringAsFactors = FALSE)
    df$input_postcode &lt;- pc
    found &lt;- bind_rows(found,df)
  } else {
    not_found &lt;- bind_rows(not_found,data,frame(postcode = pc))
  }
}

5 Geocoding with Error Handling

# Improved geocoding function with error handling
geocode_safe &lt;- function(block, streetname, max_retries = 3) {
  base_url &lt;- "https://onemap.gov.sg/api/common/elastic/search"
  address &lt;- paste(block, streetname, sep = " ")
  query &lt;- list("searchVal" = address,
                "returnGeom" = "Y",
                "getAddrDetails" = "N",
                "pageNum" = "1")

  for (attempt in 1:max_retries) {
    tryCatch({
      res &lt;- GET(base_url, query = query)
      if (res$status_code == 200) {
        restext &lt;- content(res, as = "text")
        output &lt;- fromJSON(restext)

        if (!is.null(output$results) && nrow(output$results) &gt; 0) {
          return(data.frame(
            LATITUDE = as.numeric(output$results$LATITUDE[1]),
            LONGITUDE = as.numeric(output$results$LONGITUDE[1])
          ))
        }
      }
    }, error = function(e) {
      if (attempt == max_retries) {
        warning(paste("Failed to geocode:", address))
        return(data.frame(LATITUDE = NA, LONGITUDE = NA))
      }
      Sys.sleep(0.5) # Wait before retry
    })
  }
  return(data.frame(LATITUDE = NA, LONGITUDE = NA))
}

